    "sourceText": "62.\n\n1829 తంరైరీలోని రామారావు ఇరవ్యనిలిదేళర్తివాడు.\nబగోగు్యడు. నిండా మరా్యదసుతిడు. మరా వా్యకరణాని\nరచించ్చడు. 'తెలిమఖ' ను మరాలోకి అనువదించ్చడు. ఇతని\nఇంవిల్లష్ణు ముష రైత్రనం ఆశచర్యకరన్నది. కాకుజీలో డార్మషద్ధిరు పనికి\nనిండా అరతలున్నివాడు.\n\n\n\n\nరామారావు రచించిన వా్యకరణం\n1)\nఇంవిల్లష్ణు వా్యకరణం\n2)\nమరా వా్యకరణం\n\n3)\nసంసత వా్యకరణం\n\n4)\nతెలుగు వా్యకరణం"
