    "sourceText": "79.\n\nశ్రీకాళహనుతిశ్వరా అనే మకుటంతో ఉన్ని పద్యం రజ్జటి కవి\nరచించిన శ్రీకాళహనుతిశ్వర శతకంలోది. హరు పదహారవ శకంబిద్దకి\nచెందిన కవి. శ్రీ కృషర్ణదేవరాయల ఆసార్థనంలో అషద్ధిదిగగ్గజ కవులో\nఒకడిగా ఉండి అనేక సకంక్కరాలు నోందాడు. కాళహసీతి\nమాహాతర్మ్యమును ప్రబంధలిలో రచించ్చడు. రాజులను, రాజస్నేవను\nనిరసీంచ్చడు.\n\nశ్రీకృషర్ణదేవరాయల ఆసార్థనంలో కవులు\n1)\nఅషద్ధిదికాప్పులురు\n\n2)\nఅషద్ధిదిగగ్గరైలు\n\n3)\nఅషద్ధిరవులు\n\n4)\nఅషద్ధిగరైలు"
